using System.Web.Script.Serialization;
namespace PZ3D {
 // Strict, bounded JSON used only by play-profile data and prepared heap edits.
 internal static class PlayProfileJson {
  internal static readonly UTF8Encoding Utf8=new UTF8Encoding(false,true);
  internal static JavaScriptSerializer Serializer(){return new JavaScriptSerializer{MaxJsonLength=2097152,RecursionLimit=64};}
  internal sealed class Span {internal int Start,End;internal string[] Path;}
  sealed class Reader {
   readonly string text;readonly int maximumDepth;int at;internal readonly List<Span> Arrays=new List<Span>();
   internal Reader(string text,int depth){this.text=text;maximumDepth=depth;}
   void Space(){while(at<text.Length&&char.IsWhiteSpace(text[at]))at++;}
   void Need(char c){Space();if(at>=text.Length||text[at++]!=c)throw new FormatException("JSON 语法无效。");}
   string Str(){Space();int start=at;Need('"');bool end=false;while(at<text.Length){char c=text[at++];if(c=='\\'){if(at==text.Length)throw new FormatException();at++;}else if(c=='"'){end=true;break;}}if(!end)throw new FormatException();return Serializer().Deserialize<string>(text.Substring(start,at-start));}
   void Value(int depth,string[] path){if(depth>maximumDepth)throw new FormatException("JSON 嵌套过深。");Space();if(at==text.Length)throw new FormatException();int start=at;char c=text[at];if(c=='{'){at++;var keys=new HashSet<string>(StringComparer.OrdinalIgnoreCase);Space();if(at<text.Length&&text[at]=='}'){at++;return;}while(true){string key=Str();if(!keys.Add(key))throw new FormatException("JSON 含重复字段。");Need(':');Value(depth+1,path.Concat(new[]{key}).ToArray());Space();if(at<text.Length&&text[at]=='}'){at++;return;}Need(',');}}
    else if(c=='['){at++;Space();if(at<text.Length&&text[at]==']')at++;else while(true){Value(depth+1,path.Concat(new[]{"#"}).ToArray());Space();if(at<text.Length&&text[at]==']'){at++;break;}Need(',');}Arrays.Add(new Span{Start=start,End=at,Path=path});}
    else if(c=='"')Str();else{while(at<text.Length&&!char.IsWhiteSpace(text[at])&&",]}".IndexOf(text[at])<0)at++;if(at==start)throw new FormatException();}
   }
   internal void Validate(){Value(0,new string[0]);Space();if(at!=text.Length)throw new FormatException();}
  }
  internal static Dictionary<string,object> Object(string text,int maximumBytes=1048576,int depth=12){if(text==null||Utf8.GetByteCount(text)>maximumBytes)throw new Exception("JSON 超出大小限制。");new Reader(text,depth).Validate();var result=Serializer().DeserializeObject(text) as Dictionary<string,object>;if(result==null)throw new Exception("JSON 必须为对象。");return result;}
  internal static void Keys(Dictionary<string,object> p,params string[] keys){if(p==null||p.Count!=keys.Length||keys.Any(k=>!p.ContainsKey(k)))throw new Exception("字段缺失或包含未知字段。");}
  internal static byte[] HeapArrays(byte[] before,Dictionary<string,object> normalized){
   bool bom=before.Length>=3&&before[0]==239&&before[1]==187&&before[2]==191;string text=Utf8.GetString(before,bom?3:0,before.Length-(bom?3:0));var original=Object(text,2097152,64);var scan=new Reader(text,64);scan.Validate();
   foreach(var span in scan.Arrays.OrderByDescending(s=>s.Start)){var path=span.Path;if(path.Length==0||path.Last()!="vmArgs"||path.Length%2!=1||path.Contains("#"))continue;bool heapPath=true;for(int i=0;i<path.Length-1;i+=2)if(path[i]!="windows")heapPath=false;if(!heapPath)continue;
    object value=normalized,old=original;foreach(string key in path){value=((Dictionary<string,object>)value)[key];old=((Dictionary<string,object>)old)[key];}string next=Serializer().Serialize(value);if(next!=Serializer().Serialize(old))text=text.Remove(span.Start,span.End-span.Start).Insert(span.Start,next);
   }byte[] output=Utf8.GetBytes(text);return bom?new byte[]{239,187,191}.Concat(output).ToArray():output;
  }
 }
 internal sealed class PlayProfile {
  public string id,name,targetKind,targetId,shaderId,updated;public string[] mods;public int? heapGiB;public Dictionary<string,string> settings;
  internal object View(){return new{id=id,name=name,targetKind=targetKind,targetId=targetId,mods=mods,heapGiB=heapGiB,shaderId=shaderId,settings=settings};}
  internal object Summary(){return new{id=id,name=name,targetKind=targetKind,targetId=targetId,modCount=mods.Length,updated=updated};}
 }
 internal sealed class PlayProfilePlan {
  internal string Id,Kind,Target,Stamp,Fingerprint;internal int? Heap;
  internal List<PlayProfileTransaction.Slot> Slots=new List<PlayProfileTransaction.Slot>();
  internal List<object> Changes=new List<object>();internal List<string> Warnings=new List<string>();
 }
 sealed class PlayProfiles {
  sealed class Store {public int version=1;public string selectedId="";public List<PlayProfile> profiles=new List<PlayProfile>();}
  sealed class Snapshot {internal byte[] Bytes;internal Store Store;internal string Stamp;}
  readonly Engine e;readonly string file,identity;readonly Func<bool> running;readonly Func<LauncherMemoryInfo> memory;readonly Action<string,int> boundary;
  readonly Dictionary<string,PlayProfilePlan> previews=new Dictionary<string,PlayProfilePlan>();readonly HashSet<string> recoveries=new HashSet<string>();
  internal Func<bool> CancelRequested=()=>false;
  internal const int MaxStore=1048576,MaxShare=131072;
  public PlayProfiles(Engine engine):this(engine,()=>!engine.TestMode&&engine.RuntimeRunning(),engine.TestMode?(Func<LauncherMemoryInfo>)(()=>LauncherMaintenance.CalculateMemoryInfo(32,32)):LauncherMaintenance.MemoryInfo,null){}
  internal PlayProfiles(Engine engine,Func<bool> running,Func<LauncherMemoryInfo> memory,Action<string,int> boundary){e=new Engine(engine.Game,Path.GetFullPath(engine.User),Path.GetFullPath(engine.Data),engine.TestMode,engine.ReadSteamOptions,engine.ProcessInventory){BuddySource=engine.BuddySource,ViewSource=engine.ViewSource,ModelsSource=engine.ModelsSource,Progress=engine.Progress};this.running=running;this.memory=memory;this.boundary=boundary??((phase,index)=>{if(phase=="beforeWrite"&&e.Progress!=null)e.Progress(-1,"正在应用已确认的游玩配置；尚未完成全部文件。");});file=Path.Combine(e.Data,"play-profiles",LaunchProfiles.Key(e)+".json");identity=PlayProfileTransaction.Hash(Encoding.UTF8.GetBytes(e.Game.ToUpperInvariant()+"|"+e.User.ToUpperInvariant()+"|"+e.Data.ToUpperInvariant()));}
  internal static bool Action(string action){return new[]{"playProfiles","playProfileCapture","playProfileSave","playProfileDelete","playProfileSelect","playProfilePreview","playProfileApply","playProfileExport","playProfileImport","playProfileRecover"}.Contains(action);}
  internal static string Text(Dictionary<string,object> p,string key,int limit=512){object v;if(!p.TryGetValue(key,out v)||!(v is string)||((string)v).Length>limit)throw new Exception("缺少有效文本字段："+key);return (string)v;}
  internal static void ValidatePayload(string action,Dictionary<string,object> p){switch(action){
   case "playProfiles":PlayProfileJson.Keys(p);return;
   case "playProfileCapture":PlayProfileJson.Keys(p,"stamp","name","targetKind","targetId");break;
   case "playProfileSave":PlayProfileJson.Keys(p,"stamp","id","name","targetKind","targetId","mods","heapGiB","shaderId","settings");Profile(p,false);break;
   case "playProfileDelete":case "playProfileSelect":case "playProfilePreview":case "playProfileExport":PlayProfileJson.Keys(p,"stamp","id");break;
   case "playProfileApply":PlayProfileJson.Keys(p,"id","previewStamp","confirmed");break;
   case "playProfileImport":PlayProfileJson.Keys(p,"stamp","json","confirmed");Text(p,"json",MaxShare);break;
   case "playProfileRecover":PlayProfileJson.Keys(p,"stamp","confirmed");break;
   default:throw new Exception("未知游玩配置操作。");
  }foreach(string key in p.Keys.Except(new[]{"mods","heapGiB","settings","confirmed"}))Text(p,key,key=="json"?MaxShare:512);object confirmed;if(p.TryGetValue("confirmed",out confirmed)&&(!(confirmed is bool)||!(bool)confirmed))throw new Exception("操作需要明确确认。");}
  static string Name(string s){s=s.Trim();if(s.Length==0||s.Length>100||s.Any(char.IsControl)||PathLike(s)||Regex.IsMatch(s,@"(?i)[A-Z]:[\\/]|\\\\|file://"))throw new Exception("配置名称需为 1 至 100 个可显示字符，不能是路径。");return s;}
  internal static bool Id(string s){return s!=null&&Regex.IsMatch(s,"^[a-f0-9]{32}$");}
  // One leading backslash is the game's canonical B42 metadata qualifier, not a file path.
  static bool PathLike(string s){return s.StartsWith("/",StringComparison.Ordinal)||s.StartsWith("\\\\",StringComparison.Ordinal)||s.StartsWith("\\",StringComparison.Ordinal)&&s.Substring(1).Contains('\\')||Regex.IsMatch(s,@"^[A-Za-z]:[\\/]")||s.Split(new[]{'/','\\'}).Any(p=>p=="."||p=="..");}
  static string[] Mods(object raw){if(raw is string||!(raw is IEnumerable)||raw is IDictionary)throw new Exception("mods 必须为数组。");object[] values=((IEnumerable)raw).Cast<object>().Take(2001).ToArray();if(values.Length>2000||values.Any(x=>!(x is string)))throw new Exception("模组清单超出限制或类型无效。");var ids=ModConfigurations.ValidatePreflightMods(values.Cast<string>().ToArray()).Where(id=>id!=PresentationBridge.Id).ToArray();if(ids.Any(PathLike)||ModConfigurations.Managed(ids.Select(id=>id.TrimStart('\\')).ToArray()).Length>0)throw new Exception("模组 ID 含路径或客户端组件；组件由全局安装管理。");return ids;}
  static string[] Managed(string[] active){var known=new HashSet<string>(ModConfigurations.Managed(active.Select(id=>id.TrimStart('\\')).ToArray()),StringComparer.Ordinal);return active.Where(id=>known.Contains(id.TrimStart('\\'))).ToArray();}
  static PlayProfile Profile(Dictionary<string,object> p,bool portable){string kind=portable?"normal":Text(p,"targetKind",20),target=portable?"":Text(p,"targetId",260);if(!new[]{"normal","save","server"}.Contains(kind)||kind=="normal"&&target!="")throw new Exception("启动目标类型或标识无效。");string shader=Text(p,"shaderId",200);if(shader.Any(char.IsControl)||PathLike(shader)||shader.Contains('\\')||shader.Contains('/'))throw new Exception("光影 ID 无效。");object heap;if(!p.TryGetValue("heapGiB",out heap)||heap!=null&&(!(heap is int)||(int)heap<1))throw new Exception("heapGiB 必须为正整数或 null。");object raw;if(!p.TryGetValue("mods",out raw))throw new Exception("缺少 mods。");string[] mods=Mods(raw);if(kind=="server"&&mods.Length!=0)throw new Exception("服务器游玩配置不能含普通单人模组。");object settings;if(!p.TryGetValue("settings",out settings)||!(settings is Dictionary<string,object>))throw new Exception("settings 必须为设置对象。");var changes=(Dictionary<string,object>)settings;if(changes.Count>512)throw new Exception("设置超出数量限制。");var edit=new Dictionary<string,string>();foreach(var pair in changes){if(!(pair.Value is string)||((string)pair.Value).Length>128)throw new Exception("设置值必须为有界文本。");string[] id=pair.Key.Split('|');if(id.Length!=2||!ViewpointSettings.Files.Contains(id[0]))throw new Exception("设置文件不在允许范围。");ViewpointSettings.ValidateEditable(id[1],(string)pair.Value);edit.Add(pair.Key,(string)pair.Value);}return new PlayProfile{id=portable?"":Text(p,"id",32),name=Name(Text(p,"name",100)),targetKind=kind,targetId=target,mods=mods,heapGiB=(int?)heap,shaderId=shader,settings=edit};}
  Snapshot Load(){byte[] bytes=PlayProfileTransaction.Read(file,MaxStore);var store=new Store();if(bytes!=null){try{var raw=PlayProfileJson.Object(PlayProfileJson.Utf8.GetString(bytes));PlayProfileJson.Keys(raw,"version","selectedId","profiles");if(!(raw["version"] is int)||(int)raw["version"]!=1||!(raw["selectedId"] is string)||!(raw["profiles"] is object[]))throw new Exception();var records=(object[])raw["profiles"];if(records.Length>100)throw new Exception();store.selectedId=(string)raw["selectedId"];foreach(object item in records){var p=item as Dictionary<string,object>;PlayProfileJson.Keys(p,"id","name","targetKind","targetId","mods","heapGiB","shaderId","settings","updated");var profile=Profile(p,false);DateTime updated;if(!Id(profile.id)||!DateTime.TryParse(Text(p,"updated",64),out updated)||store.profiles.Any(x=>x.id==profile.id))throw new Exception();profile.updated=(string)p["updated"];store.profiles.Add(profile);}if(store.selectedId!=""&&!store.profiles.Any(x=>x.id==store.selectedId))throw new Exception();}catch{throw new Exception("游玩配置集合损坏或版本不支持；原文件未重置。");}}return new Snapshot{Bytes=bytes,Store=store,Stamp="playProfiles:"+PlayProfileTransaction.Hash(Encoding.UTF8.GetBytes(identity+"|"+PlayProfileTransaction.Hash(bytes)))};}
  static PlayProfile Find(Snapshot s,string id){if(!Id(id))throw new Exception("游玩配置标识无效。");var p=s.Store.profiles.SingleOrDefault(x=>x.id==id);if(p==null)throw new Exception("游玩配置不存在，请刷新。");return p;}
  static void Stamp(Snapshot s,string stamp){if(string.IsNullOrEmpty(stamp)||stamp!=s.Stamp)throw new Exception("游玩配置集合已变化，请刷新后重试。");}
  T Locked<T>(Func<T> work,bool launch=false){using(var launchLock=PlayProfileTransaction.Lock(e,launch?null:file)){return work();}}
  void StorageGuard(){LauncherMaintenance.NoReparse(file);if(PlayProfileTransaction.Pending(e))throw new Exception(PlayProfileTransaction.PendingMessage);}
  void Persist(Snapshot s){StorageGuard();byte[] bytes=PlayProfileJson.Utf8.GetBytes(PlayProfileJson.Serializer().Serialize(s.Store));if(bytes.Length>MaxStore)throw new Exception("游玩配置集合超出大小限制。");PlayProfileTransaction.WriteOwnedData(file,s.Bytes,bytes,()=>{StorageGuard();Stamp(Load(),s.Stamp);});previews.Clear();}
  void Target(PlayProfile p){if(p.targetKind=="save"){SaveProfiles.ResolveSave(e,p.targetId);if(p.targetId.Split('/')[0].Equals("Multiplayer",StringComparison.OrdinalIgnoreCase))throw new Exception("联机存档只读。");}else if(p.targetKind=="server")new ServerProfiles(e.Data).TargetStamp(p.targetId);}
  void RememberRecovery(PlayProfileRecovery state){if(state.canRecover){if(recoveries.Count>=16)recoveries.Clear();recoveries.Add(state.stamp);}}
  object RememberResult(object result){var profile=result as PlayProfileResult;if(profile!=null)RememberRecovery(profile.pendingRecovery);return result;}
  object Recovery(){var state=PlayProfileTransaction.Recovery(e,running);RememberRecovery(state);return state;}
  public object List(){var s=Load();return new{stamp=s.Stamp,selectedId=s.Store.selectedId,profiles=s.Store.profiles.Select(p=>p.Summary()).ToArray(),selectedProfile=s.Store.selectedId==""?null:Find(s,s.Store.selectedId).View(),pendingRecovery=Recovery(),warnings=new string[0]};}
  object Saved(PlayProfile profile,IEnumerable<string> warnings){return new{stamp=Load().Stamp,profile=profile.View(),summary=profile.Summary(),warnings=warnings.ToArray()};}
  public object Save(Dictionary<string,object> payload){ValidatePayload("playProfileSave",payload);var profile=Profile(payload,false);return Locked<object>(()=>Locked<object>(()=>{StorageGuard();var s=Load();Stamp(s,Text(payload,"stamp"));Target(profile);profile.mods=LaunchProfiles.PersistentMods(e,profile.mods);if(profile.id==""){if(s.Store.profiles.Count>=100)throw new Exception("游玩配置数量已达上限。");profile.id=Guid.NewGuid().ToString("N");s.Store.profiles.Add(profile);}else{var old=Find(s,profile.id);s.Store.profiles[s.Store.profiles.IndexOf(old)]=profile;}profile.updated=DateTime.UtcNow.ToString("o");Persist(s);return Saved(profile,new string[0]);}),true);}
  public object Capture(Dictionary<string,object> payload){ValidatePayload("playProfileCapture",payload);return Locked<object>(()=>Locked<object>(()=>{StorageGuard();var s=Load();Stamp(s,Text(payload,"stamp"));var p=new PlayProfile{id=Guid.NewGuid().ToString("N"),name=Name(Text(payload,"name",100)),targetKind=Text(payload,"targetKind",20),targetId=Text(payload,"targetId",260),settings=new Dictionary<string,string>(),shaderId="",updated=DateTime.UtcNow.ToString("o")};if(!new[]{"normal","save","server"}.Contains(p.targetKind)||p.targetKind=="normal"&&p.targetId!="")throw new Exception("启动目标无效。");Target(p);var inputs=new Dictionary<string,byte[]>();Func<string,int,byte[]> read=(path,max)=>{var b=PlayProfileTransaction.Read(path,max);inputs[path]=b;return b;};byte[] config=read(e.Config,2097152);if(config==null)throw new Exception("启动配置不存在。");p.heapGiB=LauncherMaintenance.ProfileHeapGiB(config);var warnings=new List<string>();if(!p.heapGiB.HasValue)warnings.Add("当前未设置 Xmx；应用时保留当前堆内存。");foreach(string name in ViewpointSettings.Files){byte[] bytes=read(Path.Combine(e.User,name),1048576);if(bytes==null)continue;var doc=new PropertyDocument(bytes);foreach(var pair in doc.Values){var info=SettingsCatalog.Find(pair.Key);if(info!=null&&info.Kind!="readonly"){ViewpointSettings.ValidateEditable(pair.Key,pair.Value);p.settings[name+"|"+pair.Key]=pair.Value;}}if(name=="viewpoint-live.properties"){string shader;if(doc.Values.TryGetValue("graphics.pack",out shader))p.shaderId=shader;}}if(p.shaderId=="")warnings.Add("当前没有实际光影选择；应用时保留当前光影。");else{try{ShaderChoice(p.shaderId);}catch{warnings.Add("当前光影选择未安装或无法核实；应用前需重新核对。");}}byte[] mods=null;if(p.targetKind!="server"){string target=p.targetKind=="save"?Path.Combine(SaveProfiles.ResolveSave(e,p.targetId),"mods.txt"):e.Mods;mods=read(target,1048576);if(p.targetKind=="save"&&mods==null)mods=read(e.Mods,1048576);}p.mods=p.targetKind=="server"?new string[0]:LaunchProfiles.PersistentMods(e,SaveProfiles.DefaultMods(mods)).Except(Managed(SaveProfiles.DefaultMods(mods)),StringComparer.Ordinal).ToArray();var raw=PlayProfileJson.Object(PlayProfileJson.Serializer().Serialize(p.View()));p=Profile(raw,false);p.updated=DateTime.UtcNow.ToString("o");if(s.Store.profiles.Count>=100)throw new Exception("游玩配置数量已达上限。");foreach(var input in inputs)if(!PlayProfileTransaction.Same(input.Value,PlayProfileTransaction.Read(input.Key,input.Key==e.Config?2097152:1048576)))throw new Exception("捕获期间配置改变，请重试。");s.Store.profiles.Add(p);Persist(s);return Saved(p,warnings);}),true);}
  public object Delete(string id,string stamp){return Locked<object>(()=>{StorageGuard();var s=Load();Stamp(s,stamp);s.Store.profiles.Remove(Find(s,id));if(s.Store.selectedId==id)s.Store.selectedId="";Persist(s);return new{stamp=Load().Stamp,selectedId=s.Store.selectedId,message="已删除 launcher 游玩配置；游戏文件未修改。"};});}
  public object Select(string id,string stamp){return Locked<object>(()=>{StorageGuard();var s=Load();Stamp(s,stamp);PlayProfile p=id==""?null:Find(s,id);s.Store.selectedId=id;Persist(s);return new{stamp=Load().Stamp,selectedId=id,profile=p==null?null:p.View(),message="已选择游玩配置；应用需先预览并明确确认。"};});}
  public object Export(string id,string stamp){var s=Load();Stamp(s,stamp);var p=Find(s,id);string text=PlayProfileJson.Serializer().Serialize(new{format="OrangePlayProfile",version=1,name=p.name,mods=p.mods,heapGiB=p.heapGiB,shaderId=p.shaderId,settings=p.settings});if(PlayProfileJson.Utf8.GetByteCount(text)>MaxShare)throw new Exception("分享 JSON 超出大小限制。");return new{json=text,warnings=new[]{"分享不含本机目标、路径、凭据、Java 授权或组件安装决定。"}};}
  public object Import(string json,string stamp,bool confirmed){if(!confirmed)throw new Exception("导入需明确确认；不会自动应用。");var raw=PlayProfileJson.Object(json,MaxShare);PlayProfileJson.Keys(raw,"format","version","name","mods","heapGiB","shaderId","settings");if(!(raw["version"] is int)||(int)raw["version"]!=1||Text(raw,"format",32)!="OrangePlayProfile")throw new Exception("分享格式或版本不支持。");var profile=Profile(raw,true);return Locked<object>(()=>Locked<object>(()=>{StorageGuard();var s=Load();Stamp(s,stamp);profile.mods=LaunchProfiles.PersistentMods(e,profile.mods);if(s.Store.profiles.Count>=100)throw new Exception("游玩配置数量已达上限。");profile.id=Guid.NewGuid().ToString("N");profile.updated=DateTime.UtcNow.ToString("o");s.Store.profiles.Add(profile);Persist(s);return Saved(profile,new[]{"已导入到普通本地配置；原目标关联已清除，尚未选择或应用。"});}),true);}
  ShaderSelection ShaderChoice(string id){LauncherMaintenance.NoReparse(e.ShaderDir);var packs=Directory.Exists(e.ShaderDir)?Directory.EnumerateFiles(e.ShaderDir,"*.zip").Take(257).ToArray():new string[0];if(packs.Length>256)throw new Exception("光影目录超出数量限制。");foreach(string zip in packs){LauncherMaintenance.NoReparse(zip);if(new FileInfo(zip).Length>67108864)throw new Exception("光影包超出大小限制。");}var selection=new ShaderSelection(e.User,Path.Combine(e.Data,"backups"));var pack=selection.Packs.SingleOrDefault(p=>p.Id==id);if(pack==null||!pack.Valid)throw new Exception("光影未安装、无效或 ID 冲突。");return selection;}
  PlayProfilePlan Plan(Snapshot snapshot,PlayProfile p){Target(p);var plan=new PlayProfilePlan{Id=p.id,Kind=p.targetKind,Target=p.targetId,Heap=p.heapGiB,Stamp=snapshot.Stamp};var fingerprint=new List<string>{identity,snapshot.Stamp,PlayProfileJson.Serializer().Serialize(p.View())};Func<string,int,byte[]> read=(path,max)=>{var b=PlayProfileTransaction.Read(path,max);fingerprint.Add(path.ToUpperInvariant()+":"+PlayProfileTransaction.Hash(b));return b;};byte[] config=read(e.Config,2097152);if(config==null)throw new Exception("启动 JSON 不存在。");LauncherMaintenance.ProfileHeapGiB(config);if(p.heapGiB.HasValue){byte[] next=LauncherMaintenance.PrepareProfileHeap(config,p.heapGiB.Value,memory);if(!PlayProfileTransaction.Same(config,next)){plan.Slots.Add(new PlayProfileTransaction.Slot{target="config",before=config,after=next});plan.Changes.Add(new{kind="heap",key="heapGiB",before=LauncherMaintenance.ProfileHeapGiB(config),after=p.heapGiB});}}
   var documents=new Dictionary<string,PropertyDocument>();var originals=new Dictionary<string,byte[]>();foreach(string name in ViewpointSettings.Files){byte[] bytes=read(Path.Combine(e.User,name),1048576);originals[name]=bytes;if(bytes!=null)documents[name]=new PropertyDocument(bytes);}var updates=new Dictionary<string,Dictionary<string,string>>();foreach(var pair in p.settings){string[] id=pair.Key.Split('|');PropertyDocument doc;if(!documents.TryGetValue(id[0],out doc)||!doc.Values.ContainsKey(id[1]))throw new Exception("实际设置文件缺少参数："+pair.Key);ViewpointSettings.ValidateEditable(id[1],pair.Value);if(doc.Values[id[1]]!=pair.Value){if(!updates.ContainsKey(id[0]))updates[id[0]]=new Dictionary<string,string>();updates[id[0]][id[1]]=pair.Value;plan.Changes.Add(new{kind="setting",key=pair.Key,before=doc.Values[id[1]],after=pair.Value});}}
   if(p.shaderId!=""){var shader=ShaderChoice(p.shaderId);PropertyDocument live;if(!documents.TryGetValue("viewpoint-live.properties",out live))live=new PropertyDocument(new byte[0]);string mode;bool hasMode=live.Values.TryGetValue("graphics.mode",out mode);if(hasMode&&mode!="Modern")throw new Exception("当前渲染模式请在游戏内调整。");if(!hasMode)plan.Changes.Add(new{kind="setting",key="viewpoint-live.properties|graphics.mode",before=(string)null,after="Modern"});if(!updates.ContainsKey("viewpoint-live.properties"))updates["viewpoint-live.properties"]=new Dictionary<string,string>();updates["viewpoint-live.properties"]["graphics.pack"]=p.shaderId;updates["viewpoint-live.properties"]["graphics.mode"]="Modern";if(shader.Selected!=p.shaderId)plan.Changes.Add(new{kind="shader",key="shaderId",before=shader.Selected,after=p.shaderId});long bytes=0;foreach(var pack in shader.Packs.Where(x=>x.File!=null)){bytes+=new FileInfo(pack.File).Length;if(bytes>134217728)throw new Exception("光影累计读取预算不足。");fingerprint.Add(pack.Id+":"+DlssInstaller.HashFile(pack.File));}}
   foreach(var update in updates){PropertyDocument doc;if(!documents.TryGetValue(update.Key,out doc))doc=new PropertyDocument(new byte[0]);byte[] next=ShaderSelection.PreparedProperties(doc,update.Value);if(!PlayProfileTransaction.Same(originals[update.Key],next))plan.Slots.Add(new PlayProfileTransaction.Slot{target=update.Key,before=originals[update.Key],after=next});}
   if(p.targetKind!="server"){string target=p.targetKind=="save"?Path.Combine(SaveProfiles.ResolveSave(e,p.targetId),"mods.txt"):e.Mods;byte[] before=read(target,1048576),effective=before;if(p.targetKind=="save"&&before==null){effective=read(e.Mods,1048576);plan.Warnings.Add("所选存档继承默认模组；确认应用后才创建独立 mods.txt。");}string[] active=ModConfigurations.ValidatePreflightMods(SaveProfiles.DefaultMods(effective)),managed=Managed(active);string[] combined=LaunchProfiles.PersistentMods(e,managed.Concat(p.mods));string evidence;var sorted=ModConfigurations.SortForPlayProfile(e,combined,out evidence);if(sorted.errors.Length>0)throw new Exception(string.Join("\n",sorted.errors));combined=sorted.mods;fingerprint.Add(evidence);plan.Warnings.AddRange(sorted.warnings);byte[] next=SaveProfiles.ReplaceDefaultMods(effective,combined);if(!PlayProfileTransaction.Same(before,next)){plan.Slots.Add(new PlayProfileTransaction.Slot{target=p.targetKind=="save"?"saveMods":"defaultMods",before=before,after=next});plan.Changes.Add(new{kind="mods",key=p.targetKind=="save"?"saveMods":"defaultMods",before=active,after=combined});}}
   else fingerprint.Add(new ServerProfiles(e.Data).TargetStamp(p.targetId));if(p.heapGiB.HasValue){var info=memory();var budget=LauncherMaintenance.CalculateMemoryInfo(info.TotalGiB,info.AvailableGiB);fingerprint.Add("total:"+budget.TotalGiB);}if(plan.Slots.Any(slot=>slot.after.Length>(slot.target=="config"?2097152:1048576)))throw new Exception("应用后的配置超出单文件大小限制。");plan.Fingerprint=PlayProfileTransaction.Hash(Encoding.UTF8.GetBytes(string.Join("\n",fingerprint)));return plan;
  }
  public object Preview(string id,string stamp){var s=Load();Stamp(s,stamp);var p=Find(s,id);var errors=new List<string>();PlayProfilePlan plan=null;try{if(PlayProfileTransaction.Pending(e))throw new Exception(PlayProfileTransaction.PendingMessage);e.Guard();plan=Plan(s,p);if(plan.Fingerprint!=Plan(Load(),Find(Load(),id)).Fingerprint)throw new Exception("读取期间配置改变，请重新预览。");}catch(Exception ex){errors.Add(LauncherJournal.Sanitize(ex.Message));}string receipt="";if(plan!=null&&errors.Count==0){if(previews.Count>=16)previews.Clear();receipt="playPreview:"+Guid.NewGuid().ToString("N");previews[receipt]=plan;}return new{stamp=s.Stamp,previewStamp=receipt,profile=p.View(),canApply=errors.Count==0,changes=plan==null?new object[0]:plan.Changes.ToArray(),warnings=plan==null?new string[0]:plan.Warnings.Take(100).ToArray(),errors=errors.ToArray(),pendingRecovery=Recovery()};}
  public object Apply(string id,string previewStamp,bool confirmed){if(!confirmed)throw new Exception("应用需要当前预览和明确确认。");PlayProfilePlan issued;if(!previews.TryGetValue(previewStamp??"",out issued)||issued.Id!=id)throw new Exception("应用预览未由本机签发或已失效。");return Locked<object>(()=>Locked<object>(()=>{StorageGuard();e.Guard();var s=Load();Stamp(s,issued.Stamp);var fresh=Plan(s,Find(s,id));if(fresh.Fingerprint!=issued.Fingerprint)throw new Exception("预览后文件或目标已改变，请重新预览。");previews.Remove(previewStamp);return RememberResult(PlayProfileTransaction.Apply(e,fresh,running,memory,boundary,CancelRequested));}),true);}
  public object Recover(string stamp,bool confirmed){if(!confirmed)throw new Exception("恢复需要明确确认。");if(!recoveries.Contains(stamp??""))throw new Exception("恢复凭据未由当前本机服务签发，请刷新恢复状态。");return Locked<object>(()=>{var result=PlayProfileTransaction.Recover(e,stamp,running,boundary);recoveries.Remove(stamp);previews.Clear();return RememberResult(result);},true);}
